//! Rust port of `tests/test4.cpp`.
//!
//! Prints, one per line, the results of the four `idna` predicates applied to
//! the domain given as the first command-line argument (defaulting to
//! `example.com`).
//!
//! The library modules are pulled in by path so that this file builds both as
//! the Cargo `test4` binary and standalone via `rustc test4.rs`.

#[path = "src/idna/mod.rs"]
mod idna;

fn main() {
    if let Err(err) = idna::cli::run() {
        // A broken pipe on stdout is not worth a panic.
        eprintln!("test4: {err}");
        std::process::exit(1);
    }
}

//! Command-line front end, mirroring `tests/test4.cpp`.

use std::ffi::OsString;
use std::io::{self, Write};

use super::{is_ascii_domain, is_idn_domain, is_valid_domain, is_valid_label};

/// Value used when no domain is supplied on the command line.
pub const DEFAULT_INPUT: &str = "example.com";

/// Reads the domain to test from the process arguments.
///
/// Mirrors `if (argc > 1) input = argv[1];` -- the first argument is used when
/// present, any further arguments are ignored, and an explicitly empty first
/// argument is honoured (yielding the empty string, not the default).
///
/// This deliberately goes through [`std::env::args_os`] rather than
/// [`std::env::args`]. `args` panics on an argument that is not valid UTF-8,
/// whereas the C++ binary happily accepts one -- a lone `0xFF` byte prints
/// `1 1 0 1`. Since `std::string` imposes no encoding, staying in the byte
/// domain is what actually reproduces the reference behaviour.
pub fn input_from_args() -> Vec<u8> {
    match std::env::args_os().nth(1) {
        Some(arg) => into_bytes(arg),
        None => DEFAULT_INPUT.as_bytes().to_vec(),
    }
}

#[cfg(unix)]
fn into_bytes(arg: OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStringExt;
    arg.into_vec()
}

#[cfg(not(unix))]
fn into_bytes(arg: OsString) -> Vec<u8> {
    // No lossless `OsString` -> bytes conversion exists off Unix. Arguments
    // there are UTF-16-ish, so this is the closest available approximation.
    arg.to_string_lossy().into_owned().into_bytes()
}

/// Formats the four predicate results exactly as the C++ program prints them.
///
/// Each line is a single `1` or `0` followed by `\n`; a bare `std::cout << bool`
/// uses numeric rather than `boolalpha` formatting, and `std::endl` emits `\n`
/// (never `\r\n`). A typical run therefore writes exactly 8 bytes.
pub fn render(input: &[u8]) -> String {
    let results = [
        is_valid_domain(input),
        is_valid_label(input),
        is_ascii_domain(input),
        is_idn_domain(input),
    ];

    let mut out = String::with_capacity(results.len() * 2);
    for flag in results {
        out.push(if flag { '1' } else { '0' });
        out.push('\n');
    }
    out
}

/// Runs the program: read the argument, print the four flags.
pub fn run() -> io::Result<()> {
    let input = input_from_args();
    let mut stdout = io::stdout().lock();
    stdout.write_all(render(&input).as_bytes())?;
    // `std::endl` flushes; do the same so output ordering is identical when
    // stdout is a pipe.
    stdout.flush()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_input_matches_the_cpp_literal() {
        assert_eq!(render(DEFAULT_INPUT.as_bytes()), "1\n1\n1\n0\n");
    }

    #[test]
    fn documented_examples() {
        for domain in [
            "example.com",
            "test.org",
            "subdomain.example.com",
            "deep.nested.subdomain.example.com",
        ] {
            assert_eq!(render(domain.as_bytes()), "1\n1\n1\n0\n", "{domain}");
        }
        assert_eq!(render("例子.测试".as_bytes()), "1\n1\n0\n1\n");
    }

    #[test]
    fn empty_input() {
        assert_eq!(render(b""), "0\n0\n1\n0\n");
    }

    #[test]
    fn output_is_eight_bytes() {
        assert_eq!(render(b"example.com").len(), 8);
    }

    #[test]
    fn invalid_utf8_is_accepted_and_reported_as_idn() {
        assert_eq!(render(b"\xff"), "1\n1\n0\n1\n");
        assert_eq!(render(b"\xc3"), "1\n1\n0\n1\n");
        assert_eq!(render(b"ab\xffcd.com"), "1\n1\n0\n1\n");
    }
}

//! Domain and label validity predicates.
//!
//! # A note on strictness
//!
//! These look like they should perform structural validation -- rejecting
//! empty labels, leading hyphens, illegal characters and so on. The reference
//! C++ implementation does not. Probing it shows that *content is irrelevant*;
//! only the byte length is consulted. All of the following return `1` for both
//! `is_valid_domain` and `is_valid_label`:
//!
//! ```text
//! "."   ".."   "a."   ".a"   "a..b"   "-a.com"   "a-.com"
//! "a_b.com"    "a b.com"     "a/b.com"     "*.com"    "--"
//! ```
//!
//! A sweep of every byte from `0x01` to `0xFF`, both as a lone one-byte input
//! and embedded as `a<BYTE>b.com`, found no value that either predicate
//! rejects. Likewise 255 consecutive `.` characters is a "valid domain".
//!
//! Reimplementing these as *correct* validators would be a behavioural change,
//! so the length-only semantics are preserved deliberately.

use super::limits::{MAX_DOMAIN_LEN, MAX_LABEL_LEN};

/// Returns `true` when `input` is a valid domain name.
///
/// Equivalent to `1 <= input.len() <= 255`, counting bytes.
///
/// The upper bound applies to the string as given: no trailing dot is stripped
/// first, so a 255-byte name plus a `.` is 256 bytes and therefore invalid.
/// The bound is also purely global -- an over-long label inside an otherwise
/// short name does not make the domain invalid.
pub fn is_valid_domain(input: &[u8]) -> bool {
    within(input, MAX_DOMAIN_LEN)
}

/// Returns `true` when `input` is a valid DNS label.
///
/// Equivalent to `1 <= input.len() <= 63`, counting bytes.
///
/// The caller passes the whole input as a single label; nothing is split on
/// `.` first. That is why `"example.com"` is reported as a valid *label*.
pub fn is_valid_label(input: &[u8]) -> bool {
    within(input, MAX_LABEL_LEN)
}

/// Non-empty, and no longer than `max` bytes.
fn within(input: &[u8], max: usize) -> bool {
    !input.is_empty() && input.len() <= max
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_is_never_valid() {
        assert!(!is_valid_domain(b""));
        assert!(!is_valid_label(b""));
    }

    #[test]
    fn label_boundary_is_63_bytes() {
        assert!(is_valid_label(&vec![b'a'; 63]));
        assert!(!is_valid_label(&vec![b'a'; 64]));
    }

    #[test]
    fn domain_boundary_is_255_bytes() {
        assert!(is_valid_domain(&vec![b'a'; 255]));
        assert!(!is_valid_domain(&vec![b'a'; 256]));
    }

    #[test]
    fn limits_count_bytes_not_code_points() {
        // 21 x "例" == 63 bytes == 21 code points -> accepted.
        let sixty_three_bytes = "例".repeat(21);
        assert_eq!(sixty_three_bytes.len(), 63);
        assert!(is_valid_label(sixty_three_bytes.as_bytes()));

        // 63 x "例" == 189 bytes == 63 code points -> rejected, so the cutoff
        // cannot be measured in code points.
        let sixty_three_code_points = "例".repeat(63);
        assert_eq!(sixty_three_code_points.chars().count(), 63);
        assert!(!is_valid_label(sixty_three_code_points.as_bytes()));
    }

    #[test]
    fn content_is_ignored() {
        for input in [
            &b"."[..], b"..", b"a.", b".a", b"a..b", b"-a.com", b"a-.com",
            b"a_b.com", b"a b.com", b"a/b.com", b"*.com", b"--", b"\xff",
        ] {
            assert!(is_valid_domain(input), "domain: {input:?}");
            assert!(is_valid_label(input), "label: {input:?}");
        }
    }

    #[test]
    fn trailing_dot_is_not_stripped_before_the_length_check() {
        let mut name = vec![b'a'; 255];
        name.push(b'.');
        assert!(!is_valid_domain(&name));
    }

    #[test]
    fn over_long_label_does_not_invalidate_a_short_domain() {
        let mut name = vec![b'a'; 64];
        name.extend_from_slice(b".com");
        assert!(is_valid_domain(&name));
        assert!(!is_valid_label(&name));
    }
}
//! Classification of a domain as plain ASCII or internationalised.
//!
//! Both predicates are decided byte-wise. Neither inspects the `xn--` ACE
//! prefix: the reference implementation reports `"xn--fsq.com"` as an ASCII
//! domain and *not* an IDN, because every one of its bytes is ASCII.
//!
//! They are also decided independently of UTF-8 validity. A lone `0xFF`, a
//! truncated `0xC3`, and an overlong `0xC0 0x80` are all classified as
//! non-ASCII / IDN.

use super::limits::MAX_ASCII_BYTE;

/// Returns `true` when every byte of `input` is ASCII.
///
/// The empty string is vacuously ASCII, matching the reference implementation.
pub fn is_ascii_domain(input: &[u8]) -> bool {
    input.iter().all(|&byte| byte <= MAX_ASCII_BYTE)
}

/// Returns `true` when `input` contains at least one non-ASCII byte.
///
/// Expressed as `any` rather than as `!is_ascii_domain` so that the empty
/// string falls out correctly: it is ASCII *and* not an IDN.
pub fn is_idn_domain(input: &[u8]) -> bool {
    input.iter().any(|&byte| byte > MAX_ASCII_BYTE)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_is_ascii_but_not_idn() {
        assert!(is_ascii_domain(b""));
        assert!(!is_idn_domain(b""));
    }

    #[test]
    fn every_ascii_byte_classifies_as_ascii() {
        for byte in 0x00u8..=0x7F {
            assert!(is_ascii_domain(&[byte]), "byte {byte:#04x}");
            assert!(!is_idn_domain(&[byte]), "byte {byte:#04x}");
        }
    }

    #[test]
    fn every_high_byte_classifies_as_idn() {
        for byte in 0x80u8..=0xFF {
            assert!(!is_ascii_domain(&[byte]), "byte {byte:#04x}");
            assert!(is_idn_domain(&[byte]), "byte {byte:#04x}");
        }
    }

    #[test]
    fn punycode_prefix_is_not_treated_as_an_idn() {
        assert!(is_ascii_domain(b"xn--fsq.com"));
        assert!(!is_idn_domain(b"xn--fsq.com"));
    }

    #[test]
    fn documented_idn_example() {
        let input = "例子.测试".as_bytes();
        assert!(!is_ascii_domain(input));
        assert!(is_idn_domain(input));
    }

    #[test]
    fn complementary_for_non_empty_input() {
        for input in [&b"a"[..], b"example.com", "café".as_bytes(), b"\xc0\x80"] {
            assert_ne!(is_ascii_domain(input), is_idn_domain(input));
        }
    }
}
//! Size limits enforced by the reference implementation.
//!
//! Both limits are measured in **bytes**, not Unicode scalar values. This was
//! established by bisecting the reference binary with multi-byte input:
//!
//! | input           | bytes | code points | `is_valid_label` |
//! |-----------------|-------|-------------|------------------|
//! | `"例"` x 21     | 63    | 21          | 1                |
//! | `"例"` x 22     | 66    | 22          | 0                |
//! | `"例"` x 63     | 189   | 63          | 0                |
//! | `"ü"` x 31      | 62    | 31          | 1                |
//! | `"ü"` x 32      | 64    | 32          | 0                |
//! | `"😀"` x 15     | 60    | 15          | 1                |
//! | `"😀"` x 16     | 64    | 16          | 0                |
//!
//! A 63-code-point / 189-byte label is rejected while a 21-code-point /
//! 63-byte label is accepted, so the cutoff tracks bytes.

/// Maximum length, in bytes, of a single DNS label.
pub const MAX_LABEL_LEN: usize = 63;

/// Maximum length, in bytes, of a whole domain name.
///
/// Note this is 255, not the 253 that a strict reading of RFC 1035 would give
/// for a presentation-format name. The reference implementation compares
/// against the 255-octet wire limit directly: a 255-byte input is accepted and
/// a 256-byte input is rejected.
pub const MAX_DOMAIN_LEN: usize = 255;

/// Largest byte value considered ASCII.
pub const MAX_ASCII_BYTE: u8 = 0x7F;
//! The `idna` namespace: domain-name predicates.
//!
//! Every predicate operates on raw bytes rather than on `str`. The reference
//! C++ implementation takes a `std::string`, which is a byte container with no
//! encoding guarantees, and its length checks count *bytes*. Mirroring that
//! with `[u8]` keeps the Rust port faithful for inputs that are not valid
//! UTF-8 -- the C++ binary accepts a lone `0xFF` argument without complaint.

pub mod ascii;
pub mod cli;
pub mod limits;
pub mod validate;

// `self::` is redundant under edition 2021 but keeps a bare `rustc test4.rs`
// -- which defaults to edition 2015 -- working too.
pub use self::ascii::{is_ascii_domain, is_idn_domain};
pub use self::validate::{is_valid_domain, is_valid_label};

