use std::ffi::OsString;
use std::os::unix::ffi::OsStringExt;
use std::process::Command;

const CPP: &str = "/workspace/dataset/test4_executable";
const RS:  &str = "/output/test4";

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        // xorshift64*
        let mut x = self.0;
        x ^= x >> 12; x ^= x << 25; x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545F4914F6CDD1D)
    }
    fn below(&mut self, n: u64) -> u64 { self.next() % n }
}

fn run(bin: &str, arg: &[u8]) -> (Vec<u8>, Vec<u8>, Option<i32>) {
    let a = OsString::from_vec(arg.to_vec());
    let o = Command::new(bin).arg(&a).output().expect("spawn failed");
    (o.stdout, o.stderr, o.status.code())
}

fn esc(b: &[u8]) -> String {
    let mut s = String::new();
    for &c in b { s.push_str(&format!("\\x{:02X}", c)); }
    s
}

fn main() {
    let seed: u64 = std::env::args().nth(1)
        .and_then(|s| s.parse().ok()).unwrap_or(0xDEADBEEF12345);
    let iters: u64 = std::env::args().nth(2)
        .and_then(|s| s.parse().ok()).unwrap_or(700);
    let mode: u64 = std::env::args().nth(3)
        .and_then(|s| s.parse().ok()).unwrap_or(0);

    let mut rng = Rng(seed | 1);
    let mut cases = 0u64;
    let mut mism = 0u64;
    let mut anomalies = 0u64;

    for i in 0..iters {
        // lengths 1..=300, biased so boundaries 63/64/255/256 get hit often
        let len: usize = match mode {
            1 => {
                // boundary-focused
                let bases = [1usize,2,62,63,64,65,126,127,128,
                             191,192,254,255,256,257,299,300];
                bases[(rng.below(bases.len() as u64)) as usize]
            }
            _ => (1 + rng.below(300)) as usize,
        };

        let mut buf = Vec::with_capacity(len);
        for _ in 0..len {
            // uniform over 0x01..=0xFF  (255 values, skip NUL)
            buf.push((1 + rng.below(255)) as u8);
        }

        // occasionally force structure: valid UTF-8 multibyte, or all-high, or all-ascii
        match i % 7 {
            3 => { // all high bytes -> non-ascii/idn
                for b in buf.iter_mut() { *b = (0x80 + rng.below(0x80)) as u8; }
            }
            5 => { // all ascii printable
                for b in buf.iter_mut() { *b = (0x20 + rng.below(0x5F)) as u8; }
            }
            6 => { // valid utf8 "例" repeats truncated to len
                let s = "例".repeat(len);
                buf = s.as_bytes()[..len.min(s.len())].to_vec();
                if buf.is_empty() { buf.push(b'a'); }
            }
            _ => {}
        }

        let (co, ce, cc) = run(CPP, &buf);
        let (ro, re, rc) = run(RS,  &buf);
        cases += 1;

        if co != ro || cc != rc {
            mism += 1;
            println!("MISMATCH len={} bytes=$'{}'", buf.len(), esc(&buf));
            println!("  cpp_stdout={:?} exit={:?}", co, cc);
            println!("  rs_stdout={:?} exit={:?}", ro, rc);
        }
        if !ce.is_empty() || !re.is_empty() {
            anomalies += 1;
            println!("STDERR len={} bytes=$'{}' cpp_err={:?} rs_err={:?}",
                     buf.len(), esc(&buf), ce, re);
        }
        if cc != Some(0) || rc != Some(0) {
            anomalies += 1;
            println!("EXITNZ len={} bytes=$'{}' cpp={:?} rs={:?}",
                     buf.len(), esc(&buf), cc, rc);
        }
    }
    println!("== cases={} mismatches={} anomalies={} seed={} mode={}",
             cases, mism, anomalies, seed, mode);
}
