use std::ffi::OsString;
use std::os::unix::ffi::OsStringExt;
use std::process::Command;

const CPP: &str = "/workspace/dataset/test4_executable";
const RS:  &str = "/output/test4";

fn run(bin: &str, args: &[Vec<u8>]) -> (Vec<u8>, Vec<u8>, Option<i32>) {
    let mut c = Command::new(bin);
    for a in args { c.arg(OsString::from_vec(a.clone())); }
    let o = c.output().expect("spawn");
    (o.stdout, o.stderr, o.status.code())
}
fn esc(b: &[u8]) -> String {
    if b.len() > 40 { return format!("<{} bytes, first={:02X} last={:02X}>", b.len(), b[0], b[b.len()-1]); }
    b.iter().map(|c| format!("\\x{:02X}", c)).collect()
}

fn main() {
    let mut cases = 0; let mut mism = 0; let mut anom = 0;
    let mut check = |args: Vec<Vec<u8>>, label: String| {
        let (co, ce, cc) = run(CPP, &args);
        let (ro, re, rc) = run(RS, &args);
        cases += 1;
        if co != ro || cc != rc {
            mism += 1;
            println!("MISMATCH [{}] cpp=({:?},{:?}) rs=({:?},{:?})", label, co, cc, ro, rc);
        }
        if !ce.is_empty() || !re.is_empty() {
            anom += 1;
            println!("STDERR [{}] cpp={:?} rs={:?}", label, ce, re);
        }
        if cc != Some(0) || rc != Some(0) {
            anom += 1;
            println!("EXITNZ [{}] cpp={:?} rs={:?}", label, cc, rc);
        }
    };

    // 0) no args
    check(vec![], "no-args".into());
    // 1) empty arg
    check(vec![b"".to_vec()], "empty".into());
    // 2) every single byte 0x01..=0xFF
    for b in 1u8..=255 {
        check(vec![vec![b]], format!("single {:02X}", b));
    }
    // 3) each byte embedded: a<B>b.com
    for b in 1u8..=255 {
        let mut v = b"a".to_vec(); v.push(b); v.extend_from_slice(b"b.com");
        check(vec![v], format!("embed {:02X}", b));
    }
    // 4) length boundaries with ascii, high bytes, and mixed
    for &n in &[0usize,1,2,62,63,64,65,127,128,254,255,256,257,511,512,1023,1024,4095,4096,65535,100000] {
        for (tag, fill) in [("a", b'a'), ("hi", 0xFFu8), ("nl", b'\n'), ("cr", b'\r'), ("dot", b'.')] {
            check(vec![vec![fill; n]], format!("len {} fill {}", n, tag));
        }
    }
    // 5) flag-looking args
    for s in ["-h","--help","-","--","-v","--version","-e","--x=1","\t","\n","\r\n"," "] {
        check(vec![s.as_bytes().to_vec()], format!("flag {:?}", s));
    }
    // 6) extra args (2nd+ must be ignored)
    check(vec![b"example.com".to_vec(), b"\xff\xff".to_vec()], "two args".into());
    check(vec![b"".to_vec(), b"abc".to_vec()], "empty + extra".into());
    check(vec![b"\xff".to_vec(), b"a".to_vec(), b"b".to_vec()], "three args".into());
    // 7) UTF-8 edge: overlong, surrogate-ish, truncated, BOM
    for v in [ &b"\xC0\x80"[..], b"\xED\xA0\x80", b"\xC3", b"\xEF\xBB\xBF",
               b"\xF4\x90\x80\x80", b"\xFE\xFF", b"\x80", b"\xF0\x9F\x98\x80" ] {
        check(vec![v.to_vec()], format!("utf8edge {}", esc(v)));
    }
    // 8) multibyte at exact byte boundaries (63/64/255/256 bytes)
    for &n in &[21usize,22,85,86] {
        let s = "例".repeat(n);
        check(vec![s.into_bytes()], format!("rep-li {}", n));
    }
    // 9) high byte at position 255/256 of a long ascii string
    for &n in &[255usize, 256] {
        let mut v = vec![b'a'; n-1]; v.push(0xFF);
        check(vec![v], format!("tail-high {}", n));
        let mut v2 = vec![0xFFu8]; v2.extend(vec![b'a'; n-1]);
        check(vec![v2], format!("head-high {}", n));
    }
    println!("== edge cases={} mismatches={} anomalies={}", cases, mism, anom);
}
